using System;using System.Collections.Generic;using System.Data;using System.Data.SqlClient;using System.Diagnostics;using System.Globalization;using System.IO;using System.Text;using System.Text.RegularExpressions;using System.Web;using System.Web.Script.Serialization;
namespace WebVault { public sealed class TrashManagementHandler:IHttpHandler {
public bool IsReusable{get{return false;}}public sealed class Input{public string action{get;set;}public string id{get;set;}public string token{get;set;}public string destination{get;set;}public string path{get;set;}public bool confirm{get;set;}}public sealed class Meta{public string operationId{get;set;}public string source{get;set;}public string kind{get;set;}public string createdUtc{get;set;}public string payload{get;set;}public string state{get;set;}public string destination{get;set;}}
static JavaScriptSerializer Json(){return new JavaScriptSerializer();}static bool Exists(string p){return File.Exists(p)||Directory.Exists(p);}static void Plain(string p){if((File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new ApiFailure(409,"reparse_point_not_allowed");}
static string Resolve(string root,string p,bool allowRoot){if(String.IsNullOrEmpty(p)){if(allowRoot)return root;throw new ApiFailure(400,"invalid_path");}if(p.Length>180||p.IndexOf('\\')>=0||p.Split('/').Length>16)throw new ApiFailure(400,"invalid_path");string result=root;foreach(string n in p.Split('/')){if(n.Length==0||n.Length>100||n!=n.Trim()||n.StartsWith(".")||n.EndsWith(".")||n.IndexOfAny(Path.GetInvalidFileNameChars())>=0||Regex.IsMatch(n.Split('.')[0],@"\A(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9]|CONIN\$|CONOUT\$)\z",RegexOptions.IgnoreCase))throw new ApiFailure(400,"invalid_path");foreach(char ch in n)if(Char.IsControl(ch))throw new ApiFailure(400,"invalid_path");result=Path.Combine(result,n);if(Exists(result))Plain(result);}result=Path.GetFullPath(result);if(result.Length>240||!result.StartsWith(root+"\\",StringComparison.OrdinalIgnoreCase))throw new ApiFailure(400,"invalid_path");return result;}
static string Owned(SqlConnection db,SqlTransaction tx,ApiUser u,HttpContext c){using(SqlCommand q=new SqlCommand(@"SELECT UserId FROM auth.Users WITH(UPDLOCK,HOLDLOCK) WHERE UserId=@u AND IsActive=1 AND IsAdmin=0 AND DeletedUtc IS NULL AND MustChangePassword=0 AND EXISTS(SELECT 1 FROM auth.UserSessions WITH(UPDLOCK,HOLDLOCK) WHERE UserId=@u AND SessionId=@s AND RevokedUtc IS NULL AND ExpiresUtc>SYSUTCDATETIME() AND AbsoluteExpiresUtc>SYSUTCDATETIME())",db,tx)){q.Parameters.Add("@u",SqlDbType.Int).Value=u.UserId;q.Parameters.Add("@s",SqlDbType.BigInt).Value=u.SessionId;if(q.ExecuteScalar()==null)throw new ApiFailure(401,"unauthenticated");}using(SqlCommand q=new SqlCommand("SELECT VaultId FROM storage.UserVaults WITH(UPDLOCK,HOLDLOCK) WHERE UserId=@u",db,tx)){q.Parameters.Add("@u",SqlDbType.Int).Value=u.UserId;object v=q.ExecuteScalar();if(v==null)throw new ApiFailure(409,"vault_not_initialized");string root=Path.Combine(VaultHandler.DataRoot(c),"vaults",((Guid)v).ToString("N"));VaultHandler.PlainDirectory(root);return root;}}
static string Id(string id){if(!Regex.IsMatch(id??"","\\A[a-f0-9]{32}\\z"))throw new ApiFailure(400,"invalid_trash_id");return id;}static Meta Read(string path,string id,out string raw){Plain(path);if(new FileInfo(path).Length>8192)throw new ApiFailure(409,"trash_metadata_invalid");raw=File.ReadAllText(path,Encoding.UTF8);Meta m=Json().Deserialize<Meta>(raw);if(m==null||m.operationId!=id||m.payload!=id||(m.kind!="file"&&m.kind!="folder"))throw new ApiFailure(409,"trash_metadata_invalid");return m;}
static string Token(string raw,string payload){string data=raw;if(Exists(payload)){Plain(payload);data+="|"+File.GetLastWriteTimeUtc(payload).Ticks.ToString(CultureInfo.InvariantCulture)+"|"+(Directory.Exists(payload)?"D":new FileInfo(payload).Length.ToString(CultureInfo.InvariantCulture));}return Convert.ToBase64String(AuthCrypto.Hash(data));}
static object Item(string trash,string id){string raw;Meta m=Read(Path.Combine(trash,id+".json"),id,out raw);string p=Path.Combine(trash,id);return new{id=id,source=m.source,kind=m.kind,createdUtc=m.createdUtc,state=m.state??"active",exists=Exists(p),token=Token(raw,p)};}
static void Write(string path,Meta m){string temp=path+".tmp-"+Guid.NewGuid().ToString("N");try{byte[] b=Encoding.UTF8.GetBytes(Json().Serialize(m));using(FileStream f=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){f.Write(b,0,b.Length);f.Flush(true);}File.Replace(temp,path,null);}finally{if(File.Exists(temp))File.Delete(temp);}}
static void Scan(string p,string destination,int depth,ref int count,Stopwatch w){if(++count>2000||depth>16||p.Length>240||destination.Length>240||w.ElapsedMilliseconds>15000)throw new ApiFailure(409,"operation_tree_limit");Plain(p);if(Directory.Exists(p))foreach(string child in Directory.EnumerateFileSystemEntries(p))Scan(child,Path.Combine(destination,Path.GetFileName(child)),depth+1,ref count,w);}
static void Delete(string p,Stopwatch w){if(w.ElapsedMilliseconds>20000)throw new ApiFailure(409,"purge_partial_retry");if(!Exists(p))return;Plain(p);if(Directory.Exists(p)){foreach(string child in Directory.EnumerateFileSystemEntries(p))Delete(child,w);Directory.Delete(p,false);}else File.Delete(p);}
public void ProcessRequest(HttpContext c){bool changed=false;try{WebApi.Prepare(c);bool write=c.Request.HttpMethod=="POST";if(write)WebApi.Post(c);else WebApi.Method(c,"GET");ApiUser u=WebApi.RequireUser(c,write);if(u.IsAdmin)throw new ApiFailure(403,"personal_account_required");if(c.Request.Headers["X-WebVault-User"]!=u.UserId.ToString(CultureInfo.InvariantCulture))throw new ApiFailure(409,"session_changed");Input i=write?WebApi.Read<Input>(c):new Input{action=c.Request.QueryString["action"]??"list",id=c.Request.QueryString["id"],path=c.Request.QueryString["path"]};if(write?(i.action!="restore"&&i.action!="purge"):(i.action!="list"&&i.action!="stat"&&i.action!="read"))throw new ApiFailure(400,"invalid_action");object result;using(SqlConnection db=WebApi.Open())using(SqlTransaction tx=db.BeginTransaction()){string root=Owned(db,tx,u,c),trash=Path.Combine(root,".wv-trash");if(File.Exists(trash))throw new ApiFailure(409,"trash_invalid");if(Directory.Exists(trash))VaultHandler.PlainDirectory(trash);if(i.action=="list"){List<object> items=new List<object>();int count=0;if(Directory.Exists(trash))foreach(string meta in Directory.EnumerateFiles(trash,"*.json")){if(++count>500)throw new ApiFailure(409,"trash_list_limit");string id=Path.GetFileNameWithoutExtension(meta);try{Id(id);items.Add(Item(trash,id));}catch(Exception e){if(e is SqlException)throw;items.Add(new{id=id,error="trash_metadata_unavailable"});}}result=new{ok=true,items=items};}else{string id=Id(i.id),meta=Path.Combine(trash,id+".json"),payload=Path.Combine(trash,id);if(!File.Exists(meta))throw new ApiFailure(404,"trash_item_not_found");string raw;Meta m=Read(meta,id,out raw);if(Exists(payload))Plain(payload);if(i.action=="stat")result=new{ok=true,item=Item(trash,id)};else if(i.action=="read"){if(!Exists(payload))throw new ApiFailure(404,"trash_payload_missing");string p=Resolve(payload,i.path,true);if(Directory.Exists(p)){List<object> entries=new List<object>();foreach(string child in Directory.EnumerateFileSystemEntries(p)){if(entries.Count>=500)throw new ApiFailure(409,"too_many_entries");Plain(child);string name=Path.GetFileName(child);if(name.StartsWith("."))continue;entries.Add(new{path=String.IsNullOrEmpty(i.path)?name:i.path+"/"+name,name=name,kind=Directory.Exists(child)?"folder":"file"});}result=new{ok=true,kind="folder",entries=entries};}else{if(!File.Exists(p))throw new ApiFailure(404,"trash_payload_missing");Plain(p);if(!(String.IsNullOrEmpty(i.path)?m.source:i.path).EndsWith(".md",StringComparison.OrdinalIgnoreCase))throw new ApiFailure(415,"preview_markdown_only");using(FileStream f=new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.Read)){if(f.Length>262144)throw new ApiFailure(413,"note_too_large");using(StreamReader reader=new StreamReader(f,new UTF8Encoding(false,true),true))result=new{ok=true,kind="file",text=reader.ReadToEnd()};}}}else{if(!String.Equals(Token(raw,payload),i.token,StringComparison.Ordinal))throw new ApiFailure(409,"trash_changed_refresh");Stopwatch watch=Stopwatch.StartNew();int count=0;if(i.action=="restore"){if(m.state=="purging"||m.state=="restoring")throw new ApiFailure(409,"trash_pending_operation");if(!Exists(payload))throw new ApiFailure(404,"trash_payload_missing");string relative=String.IsNullOrEmpty(i.destination)?m.source:i.destination;string dest=Resolve(root,relative,false);if(Exists(dest))throw new ApiFailure(409,"destination_exists_choose_other_name");if(!Directory.Exists(Path.GetDirectoryName(dest)))throw new ApiFailure(409,"parent_missing_create_or_choose_folder");VaultHandler.PlainDirectory(Path.GetDirectoryName(dest));if(m.kind=="file"&&m.source.EndsWith(".md",StringComparison.OrdinalIgnoreCase)&&!relative.EndsWith(".md",StringComparison.OrdinalIgnoreCase))throw new ApiFailure(400,"markdown_extension_required");Scan(payload,dest,0,ref count,watch);m.state="restoring";m.destination=relative;changed=true;Write(meta,m);if(Directory.Exists(payload))Directory.Move(payload,dest);else File.Move(payload,dest);m.state="restored";Write(meta,m);File.Delete(meta);result=new{ok=true,destination=relative};}else{if(!i.confirm)throw new ApiFailure(400,"explicit_delete_confirmation_required");if(m.state=="restoring")throw new ApiFailure(409,"trash_pending_operation");if(Exists(payload))Scan(payload,payload,0,ref count,watch);m.state="purging";changed=true;Write(meta,m);Delete(payload,watch);File.Delete(meta);result=new{ok=true,id=id};}}}tx.Commit();}WebApi.Reply(c,200,result);}catch(Exception e){if(changed){Trace.TraceError("Trash management outcome needs refresh: {0}",e.GetType().Name);WebApi.Reply(c,503,new{ok=false,error="trash_operation_incomplete_refresh"});}else if(e is FileNotFoundException||e is DirectoryNotFoundException)WebApi.Error(c,new ApiFailure(404,"trash_item_not_found"));else WebApi.Error(c,e);}}
} }
